import {photoViewFromWorld,drawOriginalOctavia} from './racing-photo-views.mjs?v=20261027';
import {drawExhaust2D,boostVisual} from './racing-speed-effects.mjs?v=20261026-performance';
import {drawNitroBadge} from './racing-nitro-badge.mjs?v=20261026-nitro';
import {nitroVisible,availableNitros} from './racing-nitro.mjs?v=20261026-nitro';
import {drivingCamera,cameraProject} from './racing-cameras.mjs?v=20261026-alineados';
import {createCircuitEnvironment} from './racing-environment.mjs?v=20261025-aerial';
import {teslaFireTime} from './racing-cinematic-state.mjs';
import {drawCarFire} from './racing-fire2d.mjs';
const environments=new Map(),images={};
if(typeof Image!=='undefined')for(const [key,path]of [['grass','assets/cesped-circuito.jpg'],['asphalt','assets/track3d/asphalt-color.jpg']]){const image=new Image();image.onload=()=>images[key]=image;image.src=path;}
export function drawExternalFallback(ctx,race,width,height,view,photos){
 const pose=drivingCamera(race,view,width/height);pose.fov+=boostVisual(race)*(view==='aerial'?5:10);const layout=pose.layout,project=p=>cameraProject(p,pose,width,height),half=race.settings.roadHalf;
 const sky=ctx.createLinearGradient(0,0,0,height);sky.addColorStop(0,'#8dabbc');sky.addColorStop(.43,'#dae0de');sky.addColorStop(.44,'#5d7050');sky.addColorStop(1,'#38472f');ctx.fillStyle=sky;ctx.fillRect(0,0,width,height);
 const faces=[];function face(points,color,texture){const p=points.map(project);if(p.some(v=>!v))return;faces.push({p,color,texture,depth:p.reduce((a,b)=>a+b.depth,0)/p.length});}
 function ribbon(d1,d2,a,b,color,texture){const f=layout.frame(d1),g=layout.frame(d2);face([[f.p[0]+f.r[0]*a,f.p[1]+.02,f.p[2]+f.r[2]*a],[f.p[0]+f.r[0]*b,f.p[1]+.02,f.p[2]+f.r[2]*b],[g.p[0]+g.r[0]*b,g.p[1]+.02,g.p[2]+g.r[2]*b],[g.p[0]+g.r[0]*a,g.p[1]+.02,g.p[2]+g.r[2]*a]],color,texture);}
 // Nearby fragments of the same closed layout, including neighbouring bends.
 for(let d=0;d<layout.length;d+=6){const p=layout.position(d);if(Math.hypot(p[0]-pose.car[0],p[2]-pose.car[2])>420)continue;ribbon(d,d+6,-half-2,half+2,'#a59b84');ribbon(d,d+6,-half,half,'#44494a','asphalt');for(const side of [-1,1]){ribbon(d,d+6,side*half,side*(half+.65),Math.floor(d/6)%2?'#c4c5ba':'#8e3b35');ribbon(d,d+6,side*(half-.20),side*(half-.12),'#d9dbcf');}if(d%18<6)ribbon(d,d+5,-.06,.06,'#d4d6cc');}
 faces.sort((a,b)=>b.depth-a.depth);for(const f of faces){ctx.beginPath();f.p.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=f.color;ctx.fill();if(f.texture&&images[f.texture]){ctx.save();ctx.clip();ctx.globalAlpha=.18;ctx.fillStyle=ctx.createPattern(images[f.texture],'repeat');ctx.fillRect(0,0,width,height);ctx.restore();}}
 const key=race.circuit+':'+race.difficulty;let env=environments.get(key);if(!env){env=createCircuitEnvironment(layout,half,race.circuit||'club');environments.set(key,env);if(environments.size>3)environments.delete(environments.keys().next().value);}
 const objects=[];for(const pickup of availableNitros(race)){const f=layout.frame(pickup.distance),p=project([f.p[0],f.p[1]+1.65,f.p[2]]);if(p&&p.depth<450)objects.push({p,nitro:true});}for(const tree of env.trees){const p=project(tree.p);if(p&&p.depth<300)objects.push({p,tree});}
 const cars=[{distance:race.distance,x:race.x,player:true,color:race.playerPaint},...race.rivals];for(const car of cars){const f=layout.frame(car.distance),point=[f.p[0]+f.r[0]*car.x*half,f.p[1]+.02,f.p[2]+f.r[2]*car.x*half],p=project(point);if(p&&p.depth<360)objects.push({p,car});}
 objects.sort((a,b)=>b.p.depth-a.p.depth);for(const o of objects){const {p}=o;if(o.nitro){drawNitroBadge(ctx,race,p.x,p.y,p.scale*3.5);continue;}if(o.tree){const r=o.tree.radius*p.scale,h=o.tree.height*p.scale;ctx.fillStyle='#16251c';ctx.fillRect(p.x-r*.12,p.y-h*.55,r*.24,h*.55);const g=ctx.createRadialGradient(p.x-r*.3,p.y-h,.3,p.x,p.y-h,r);g.addColorStop(0,'#7b8b60');g.addColorStop(1,'#31482c');ctx.fillStyle=g;ctx.beginPath();ctx.ellipse(p.x,p.y-h*.75,r,h*.45,0,0,Math.PI*2);ctx.fill();continue;}
 const car=o.car,w=Math.max(1,p.scale*1.9),image=car.player?photos.playerRear:car.model==='tesla-model-3'?photos.tesla:photos.rival;ctx.fillStyle='#0006';ctx.beginPath();ctx.ellipse(p.x,p.y,w*.6,w*.18,0,0,Math.PI*2);ctx.fill();if(view==='aerial'){
 const f=layout.frame(car.distance),front=project([f.p[0]+f.t[0]*2,f.p[1],f.p[2]+f.t[2]*2]),back=project([f.p[0]-f.t[0]*2,f.p[1],f.p[2]-f.t[2]*2]);const angle=front&&back?Math.atan2(front.x-back.x,-front.y+back.y):0,h=w*1.85;ctx.save();ctx.translate(p.x,p.y-h*.35);ctx.rotate(angle);const color=car.model==='tesla-model-3'?'#eeefed':race.photoCars!==false?'#111418':car.player?({red:'#a32a32',black:'#17191b',grey:'#6a6e70',white:'#e5e7e5'})[car.color]||'#2265a0':'#2265a0';ctx.fillStyle='#101318';for(const side of [-1,1])for(const axle of [-.28,.28])ctx.fillRect(side*w*.48-w*.06,axle*h-w*.18,w*.12,w*.36);const paint=ctx.createLinearGradient(-w*.5,0,w*.5,0);paint.addColorStop(0,'#1c2b36');paint.addColorStop(.25,color);paint.addColorStop(.65,color);paint.addColorStop(1,'#263947');ctx.fillStyle=paint;ctx.beginPath();ctx.roundRect(-w*.45,-h*.5,w*.9,h,w*.16);ctx.fill();ctx.fillStyle='#192a35';ctx.fillRect(-w*.34,-h*.28,w*.68,h*.17);ctx.fillRect(-w*.33,h*.24,w*.66,h*.12);ctx.fillStyle=car.model==='tesla-model-3'?'#253139':color;ctx.fillRect(-w*.32,-h*.08,w*.64,h*.28);ctx.fillStyle='#d6e3e7';for(const side of [-1,1])ctx.fillRect(side*w*.3-w*.08,-h*.45,w*.16,h*.025);ctx.fillStyle='#d62432';for(const side of [-1,1])ctx.fillRect(side*w*.3-w*.08,h*.44,w*.16,h*.035);if(car.player)drawExhaust2D(ctx,race,0,h*.48,w,{aerial:true});ctx.restore();
 }else if(car.model!=='tesla-model-3'&&race.photoCars!==false&&(()=>{const frame=layout.frame(car.distance),position=[frame.p[0]+frame.r[0]*car.x*half,frame.p[1],frame.p[2]+frame.r[2]*car.x*half],key=photoViewFromWorld(frame,position,pose.position);return key&&drawOriginalOctavia(ctx,photos.originalOctavia,key,p.x,p.y,p.scale*1.49,car.distance);})()){}else if(image&&(car.model==='tesla-model-3'||race.photoCars===false)){const h=w*image.height/image.width;ctx.drawImage(image,p.x-w/2,p.y-h,w,h);}else{ctx.fillStyle=car.model==='tesla-model-3'?'#f3f1ec':race.photoCars!==false?'#111418':'#1465a3';ctx.fillRect(p.x-w/2,p.y-w*.7,w,w*.7);}
 if(car.player&&view!=='aerial')drawExhaust2D(ctx,race,p.x,p.y,w);
 if(car.model==='tesla-model-3')drawCarFire(ctx,p.x,p.y,w,teslaFireTime(race));}
 return pose;
}
